// Textos de Eikholt (prefijo ek.): el mapa aparte de la capital, sus lugares y lo que dice su gente.
I18N.textos({
  // ---------- la ciudad ----------
  "ek.nombre": { es: "Eikholt, la ciudad del Roble", en: "Eikholt, city of the Oak" },
  "ek.llegando": { es: "Las puertas de Eikholt", en: "The gates of Eikholt" },
  // la gente sin nombre de la ciudad
  "av.nombre_ek_vecino": { es: "Vecino", en: "Townsman" },
  "av.nombre_ek_vecina": { es: "Vecina", en: "Townswoman" },
  "av.nombre_ek_nino": { es: "Chico de Eikholt", en: "Eikholt child" },
  "av.nombre_ek_vendedor": { es: "Puestera", en: "Stallholder" },
  "av.nombre_ek_recluta": { es: "Recluta de la Guardia", en: "Guard recruit" },
  "av.nombre_ek_viajero": { es: "Caravanero", en: "Caravaneer" },
  "av.nombre_ek_pescador": { es: "Balsero", en: "Raftsman" },
  "av.nombre_ek_guardia": { es: "Guardia del Roble", en: "Oak Guard" },
  "ek.dice_vecino_0": { es: "Si te perdés, buscá la copa del Roble: todas las calles terminan ahí.", en: "If you get lost, look for the Oak's crown: every street ends there." },
  "ek.dice_vecino_1": { es: "Las tablillas de la Puerta del Sur cuentan a los que salieron. Ojalá ninguna se quede oscura.", en: "The tablets at the South Gate count those who went out. I hope none stays dark." },
  "ek.dice_vecino_2": { es: "De noche no salgas por el norte. Los lobos ya llegan hasta el corral de las caravanas.", en: "Don't go out the north at night. The wolves come right up to the caravan pen now." },
  "ek.dice_vecino_3": { es: "Mi abuelo decía que las piedras de la cúpula cantaban. Ya no las oigo.", en: "My grandfather said the dome stones used to sing. I don't hear them anymore." },
  "ek.dice_vecino_4": { es: "Ása no cobra lo mismo a todos. Al que hizo algo por la ciudad le hace precio.", en: "Ása doesn't charge everyone the same. Whoever did something for the city gets a better price." },
  "ek.dice_vecino_5": { es: "En el Hongo Dorado Sølve canta lo que pasó ayer como si fuera de hace cien años.", en: "At the Golden Mushroom, Sølve sings about yesterday as if it were a hundred years ago." },
  "ek.dice_vecino_6": { es: "La Casa de las Lindes es más vieja que la empalizada. La losa del patio, más vieja todavía.", en: "The House of Bounds is older than the palisade. The slab in its yard, older still." },
  "ek.dice_vecino_7": { es: "Cuando suena la campana dos veces, cerramos los portones. Ya pasó una vez este invierno.", en: "When the bell rings twice, we shut the gates. It happened once already this winter." },
  "ek.dice_vecina_0": { es: "Las cintas de las raíces son promesas. Si atás una, la tenés que cumplir.", en: "The ribbons on the roots are promises. If you tie one, you must keep it." },
  "ek.dice_vecina_1": { es: "Thora cura sin preguntar de dónde viene la herida. Por eso siempre hay cola.", en: "Thora heals without asking where the wound came from. That's why there's always a line." },
  "ek.dice_vecina_2": { es: "Los hongos de Ragna brillan apenas de noche. Los chicos juran que hablan.", en: "Ragna's mushrooms glow faintly at night. The children swear they talk." },
  "ek.dice_vecina_3": { es: "El pozo de Gudrun nunca se secó. Ni en el año sin lluvia.", en: "Gudrun's well never ran dry. Not even in the year without rain." },
  "ek.dice_vecina_4": { es: "Los de Hrafngard miran todo como si ya fuera de su rey.", en: "The Hrafngard folk look at everything as if it already belonged to their king." },
  "ek.dice_vecina_5": { es: "Subí al mirador una vez. Desde ahí el bosque parece un mar que no termina.", en: "I climbed the lookout once. From up there the forest looks like an endless sea." },
  "ek.dice_vecina_6": { es: "La sal de Skeldra viene en balsa por el río. Cuando el río baja, sube el precio.", en: "Skeldra salt comes by raft down the river. When the river drops, the price climbs." },
  "ek.dice_vecina_7": { es: "Si vas a la Asamblea, no te sientes en una piedra que no es tuya.", en: "If you go to the Thing, don't sit on a stone that isn't yours." },
  "ek.dice_nino_0": { es: "¡Esa espada es más grande que yo!", en: "That sword is bigger than me!" },
  "ek.dice_nino_1": { es: "Apuesto a que no llegás corriendo hasta el pozo antes que yo.", en: "Bet you can't run to the well before me." },
  "ek.dice_nino_2": { es: "La piedra negra del Ting no se toca. Eirik la tocó y le salió un sarpullido.", en: "You don't touch the Thing's black stone. Eirik did and got a rash." },
  "ek.dice_nino_3": { es: "¿Viste al buey del corral? Se llama Trueno pero tiene miedo de las gallinas.", en: "Did you see the ox in the pen? His name is Thunder but he's scared of the hens." },
  "ek.dice_nino_4": { es: "Cuando sea grande voy a ser guardasendas como Eydis.", en: "When I grow up I'll be a pathwarden like Eydis." },
  "ek.dice_vendedor_0": { es: "Hongos dorados, recién cortados. Para el caldo o para la fiebre.", en: "Golden mushrooms, freshly cut. For the stew or for a fever." },
  "ek.dice_vendedor_1": { es: "Esta piel es de oso del zarzal. No pregunto quién lo cazó.", en: "This hide is from a bramble bear. I don't ask who hunted it." },
  "ek.dice_vendedor_2": { es: "Cerámica de la costa. Si se rompe en el camino, es tu suerte, no la mía.", en: "Coastal pottery. If it breaks on the road, that's your luck, not mine." },
  "ek.dice_vendedor_3": { es: "Obsidiana de Eldrakar. Corta mejor que el hierro y no se oxida.", en: "Eldrakar obsidian. Cuts better than iron and never rusts." },
  "ek.dice_vendedor_4": { es: "El pescado de hoy viene del muelle de balsas. El de ayer, mejor no.", en: "Today's fish comes from the raft dock. Yesterday's, better not." },
  "ek.dice_vendedor_5": { es: "Bajo la copa no llueve nunca del todo. Por eso el mercado está acá.", en: "It never quite rains under the crown. That's why the market is here." },
  "ek.dice_farolero_0": { es: "Cada farol tiene su mecha y su carácter. Este de acá siempre se hace rogar.", en: "Every lamp has its wick and its temper. This one always makes me beg." },
  "ek.dice_farolero_1": { es: "Al alba los apago de a uno, igual que los prendí. Ni uno más, ni uno menos.", en: "At dawn I put them out one by one, just as I lit them. Not one more, not one less." },
  "ek.dice_farolero_2": { es: "Mi abuelo prendía estos mismos faroles. Él decía que la noche respeta a la ciudad que se alumbra.", en: "My grandfather lit these very lamps. He said the night respects a city that lights itself." },
  "ek.dice_farolero_3": { es: "No me demores, forastero, que la plaza se queda a oscuras.", en: "Don't hold me up, outsider, or the square will go dark." },
  "ek.dice_borracho_0": { es: "¡Forastero! Vos… vos me caés bien. ¿Te conté lo del jabalí? Era así de grande.", en: "Outsider! You… I like you. Did I tell you about the boar? It was this big." },
  "ek.dice_borracho_1": { es: "La hidromiel de Ulf no se toma, se pelea. Y yo perdí.", en: "Ulf's mead isn't drunk, it's fought. And I lost." },
  "ek.dice_borracho_2": { es: "Shh… no le digas a mi mujer que estoy acá. Estoy en la ronda. Haciendo la ronda.", en: "Shh… don't tell my wife I'm here. I'm on watch. Doing the watch." },
  "ek.dice_borracho_3": { es: "¿Por qué el Roble se mueve? Ah, no, soy yo.", en: "Why is the Oak moving? Oh, no, it's me." },
  "ek.dice_borracho_4": { es: "Sølve canta tan lindo que me hizo llorar dos veces. La tercera fue por la cuenta.", en: "Sølve sings so beautifully he made me cry twice. The third time was the bill." },
  "ek.fama_jotunn_0": { es: "¿Es cierto que tumbaste al jötunn de hielo? En el Hongo no se habla de otra cosa.", en: "Is it true you brought down the frost jötunn? They talk of nothing else at the Mushroom." },
  "ek.fama_jotunn_1": { es: "Dicen que Hrímnir cayó y que el frío se fue con él. Gracias, forastero.", en: "They say Hrímnir fell and the cold left with him. Thank you, outsider." },
  "ek.fama_holmr_0": { es: "Te vi en la hólmganga. Hallbera no le da la mano a cualquiera.", en: "I saw you at the holmgang. Hallbera doesn't shake just anyone's hand." },
  "ek.fama_holmr_1": { es: "Ganaste sobre la piel sin derramar sangre. Eso es saber pelear.", en: "You won on the hide without spilling blood. That's knowing how to fight." },
  "ek.fama_contrato_0": { es: "El poste del Puesto tiene una bestia menos. Algunos ya duermen mejor.", en: "The Outpost post has one beast fewer. Some already sleep better." },
  "ek.fama_contrato_1": { es: "Cobraste un contrato de caza, ¿no? Se nota en cómo caminás.", en: "You collected on a hunting contract, didn't you? It shows in how you walk." },
  "ek.fama_bandidos_0": { es: "Los Sin Linde ya no se ríen tanto en los caminos. Algo tuviste que ver.", en: "The Lawless don't laugh so much on the roads anymore. You had something to do with it." },
  "ek.fama_bandidos_1": { es: "Mi primo traía sal y no le robaron. Dice que fue gracias a vos.", en: "My cousin brought salt and wasn't robbed. He says it was thanks to you." },
  "ek.fama_aranas_0": { es: "¿Cortaste un nido de arañas? Yo no me acerco a esas telas ni loca.", en: "You cut down a spider nest? I wouldn't go near those webs for anything." },
  "ek.fama_aranas_1": { es: "Los leñadores dicen que el bosque está más limpio de telas. Bien hecho.", en: "The woodcutters say the forest is clearer of webs. Well done." },
  "ek.fama_caceria_0": { es: "Sobreviviste a la Cacería Salvaje. Hay que tener las tripas bien puestas.", en: "You survived the Wild Hunt. That takes guts." },
  "ek.fama_caceria_1": { es: "La noche del cuerno cerramos todo. Y vos afuera… ¿cómo seguís vivo?", en: "On the night of the horn we shut everything. And you were out there… how are you still alive?" },
  "ek.fama_nivel_0": { es: "Ya no tenés cara de recién llegado. El bosque te curtió.", en: "You don't look like a newcomer anymore. The forest has toughened you." },
  "ek.fama_nivel_1": { es: "Los chicos juegan a ser vos. Uno se pinta la cara de rojo.", en: "The kids play at being you. One paints his face red." },
  "ek.ld_grito": { es: "¡Al ladrón! ({0}) ¡Corré, que se escapa!", en: "Stop, thief! ({0}) Run, he's getting away!" },
  "ek.ld_atrapado": { es: "¡Está bien, está bien! Tomá, devolvé esto. Era para mis hermanos…", en: "All right, all right! Here, give this back. It was for my brothers…" },
  "ek.ld_gracias": { es: "¡Lo agarraste! Tomá, por las piernas y por la honra del puesto.", en: "You caught him! Here, for your legs and for the stall's honor." },
  "ek.ld_premio": { es: "Atrapaste al ratero: +{0} de plata", en: "You caught the thief: +{0} silver" },
  "ek.ld_escapo": { es: "El ratero se perdió entre las casas", en: "The thief vanished among the houses" },
  "ek.ga_aviso": { es: "Se escaparon las gallinas del corral: arrealas caminando por detrás hasta su gallinero", en: "The corral hens got loose: herd them back to their coop by walking behind them" },
  "ek.ga_una": { es: "Una gallina de vuelta: {0} de {1}", en: "One hen back: {0} of {1}" },
  "ek.ga_listo": { es: "Las siete adentro. Más difícil que un lobo.", en: "All seven inside. Harder than a wolf." },
  "ek.ga_premio": { es: "La granjera del corral te paga {0} de plata", en: "The corral farmer pays you {0} silver" },
  "ek.hoy_gallinas": { es: "se escaparon las gallinas del corral (9 a 17)", en: "the corral hens are loose (9 to 17)" },
  "ek.pu_accion": { es: "Pulseada sobre el barril · {0} de plata", en: "Arm-wrestle on the barrel · {0} silver" },
  "ek.pu_sin_plata": { es: "Hacen falta {0} de plata para apostar", en: "You need {0} silver to bet" },
  "ek.pu_empieza": { es: "¡Codo en el barril! Machacá atacar para empujar", en: "Elbow on the barrel! Mash attack to push" },
  "ek.pu_marcador": { es: "Quedan {0} s", en: "{0} s left" },
  "ek.pu_ayuda": { es: "{0} o E, lo más rápido que puedas", en: "{0} or E, as fast as you can" },
  "ek.pu_ganaste": { es: "¡Ganaste!", en: "You win!" },
  "ek.pu_perdiste": { es: "Te ganó", en: "He beat you" },
  "ek.pu_gane": { es: "Fuerte el brazo, flojas las piernas. Otra noche será.", en: "Strong arm, weak legs. Another night, friend." },
  "ek.pu_gane_otra": { es: "Esta ya la conocía.", en: "I knew that one already." },
  "ek.pu_perdi": { es: "El hidromiel le da fuerza. O eso me digo.", en: "Mead gives him strength. Or so I tell myself." },
  "ek.pu_premio": { es: "Ganás {0} de plata en la pulseada", en: "You win {0} silver at arm-wrestling" },
  "ek.pu_devuelta": { es: "Te devuelve los {1} de la apuesta", en: "He gives back your {1} silver bet" },
  "av.nombre_ek_cuentista": { es: "Cuentacuentos", en: "Storyteller" },
  "ek.dice_cuentista_0": { es: "Vuelvo al anochecer. Las historias no se cuentan con sol.", en: "Come back at nightfall. Stories aren't told in sunlight." },
  "ek.dice_cuentista_1": { es: "Vengo del norte, de fuego en fuego. Cada uno me paga con un plato.", en: "I come from the north, fire to fire. Each one pays me with a bowl." },
  "ek.dice_cuentista_2": { es: "Tengo ocho historias y una noche para cada una.", en: "I have eight stories and one night for each." },
  "ek.cu_accion": { es: "Escuchar · {0}", en: "Listen · {0}" },
  "ek.cu_accion_otra": { es: "Escuchar otra vez · {0}", en: "Listen again · {0}" },
  "ek.cu_abre": { es: "Sentate, forastero. Esta noche: {0}.", en: "Sit, stranger. Tonight: {0}." },
  "ek.cu_aprendido": { es: "Historia aprendida: {0} ({1} de {2})", en: "Story learned: {0} ({1} of {2})" },
  "ek.hoy_cuento": { es: "de noche, junto al fuego de los forasteros: {0}", en: "at night, by the strangers' fire: {0}" },
  "ek.cu_0_titulo": { es: "La pesca de Thor", en: "Thor's fishing trip" },
  "ek.cu_0_0": { es: "Thor salió a pescar con el gigante Hymir y puso de carnada la cabeza del mejor buey del gigante.", en: "Thor went fishing with the giant Hymir and baited his hook with the head of the giant's finest ox." },
  "ek.cu_0_1": { es: "Remó tan lejos que Hymir temblaba: ahí abajo dormía la Serpiente del Mundo.", en: "He rowed so far out that Hymir trembled: down there slept the World Serpent." },
  "ek.cu_0_2": { es: "La Serpiente mordió, Thor tiró, sus pies atravesaron el fondo de la barca y quedó parado en el lecho del mar.", en: "The Serpent bit, Thor pulled, his feet broke through the hull and he stood on the seabed itself." },
  "ek.cu_0_3": { es: "Cuando alzó el martillo, Hymir cortó el sedal del miedo. Por eso la Serpiente sigue ahí, esperando.", en: "As he raised the hammer, Hymir cut the line in fear. That's why the Serpent is still there, waiting." },
  "ek.cu_0_eromash": { es: "Hay pescas que es mejor no terminar.", en: "Some catches are better left unfinished." },
  "ek.cu_1_titulo": { es: "Fenrir y la mano de Týr", en: "Fenrir and Týr's hand" },
  "ek.cu_1_0": { es: "El lobo Fenrir crecía tanto que los dioses le tuvieron miedo y quisieron atarlo.", en: "The wolf Fenrir grew so large that the gods feared him and wanted him bound." },
  "ek.cu_1_1": { es: "Rompió dos cadenas jugando. La tercera la hicieron los enanos con el ruido del gato y la barba de la mujer.", en: "He broke two chains in play. The third the dwarves made from a cat's footfall and a woman's beard." },
  "ek.cu_1_2": { es: "Fenrir olió el engaño y pidió que uno pusiera la mano en su boca como prenda. Solo Týr se animó.", en: "Fenrir smelled a trick and asked that one of them put a hand in his mouth as pledge. Only Týr dared." },
  "ek.cu_1_3": { es: "La cinta no cedió. Týr perdió la mano, y desde entonces la palabra dada se jura por él.", en: "The ribbon held. Týr lost his hand, and ever since, oaths are sworn by his name." },
  "ek.cu_1_eromash": { es: "Una mano por una promesa. Caro, pero se cumplió.", en: "A hand for a promise. Costly, but it was kept." },
  "ek.cu_2_titulo": { es: "El ojo de Odín", en: "Odin's eye" },
  "ek.cu_2_0": { es: "Bajo una raíz del gran fresno está el pozo de Mímir, y quien bebe de él sabe lo que fue y lo que será.", en: "Beneath a root of the great ash lies Mímir's well, and whoever drinks from it knows what was and what will be." },
  "ek.cu_2_1": { es: "Odín fue a pedir un trago. Mímir no quiso plata ni oro: pidió un ojo.", en: "Odin came to ask for a drink. Mímir wanted neither silver nor gold: he asked for an eye." },
  "ek.cu_2_2": { es: "Odín se lo sacó y lo dejó en el fondo del agua. Bebió, y vio todo, también su propio final.", en: "Odin plucked it out and left it at the bottom of the water. He drank, and saw everything, his own end as well." },
  "ek.cu_2_3": { es: "Dicen que en noches quietas el ojo brilla en el pozo, mirando para arriba.", en: "They say on still nights the eye shines in the well, looking up." },
  "ek.cu_2_eromash": { es: "Saber tu final y seguir andando. Eso es coraje.", en: "Knowing your end and walking on anyway. That's courage." },
  "ek.cu_3_titulo": { es: "Las manzanas de Iðunn", en: "Iðunn's apples" },
  "ek.cu_3_0": { es: "Iðunn guardaba las manzanas que mantienen jóvenes a los dioses.", en: "Iðunn kept the apples that keep the gods young." },
  "ek.cu_3_1": { es: "Loki, atrapado por un gigante águila, juró entregarla, y la llevó al bosque con mentiras.", en: "Loki, caught by a giant in eagle shape, swore to hand her over, and lured her into the woods with lies." },
  "ek.cu_3_2": { es: "Sin manzanas, los dioses se llenaron de canas y arrugas, y miraron a Loki.", en: "Without the apples, the gods grew gray and wrinkled, and they looked at Loki." },
  "ek.cu_3_3": { es: "Loki voló como halcón, la volvió nuez y la trajo en las garras. El gigante que lo siguió se quemó en el muro.", en: "Loki flew as a falcon, turned her into a nut and carried her in his claws. The giant who chased him burned at the wall." },
  "ek.cu_3_eromash": { es: "Loki arregla lo que rompe. A veces.", en: "Loki fixes what he breaks. Sometimes." },
  "ek.cu_4_titulo": { es: "El muro de Asgard", en: "The wall of Asgard" },
  "ek.cu_4_0": { es: "Un constructor ofreció levantar un muro alrededor de Asgard en un solo invierno.", en: "A builder offered to raise a wall around Asgard in a single winter." },
  "ek.cu_4_1": { es: "Pidió el sol, la luna y a Freyja. Los dioses aceptaron, seguros de que no llegaría.", en: "He asked for the sun, the moon and Freyja. The gods agreed, sure he would never make it." },
  "ek.cu_4_2": { es: "Pero su caballo cargaba piedras como montañas. Faltando tres días, el muro estaba casi listo.", en: "But his stallion hauled stones like mountains. With three days left, the wall was almost done." },
  "ek.cu_4_3": { es: "Loki se volvió yegua y se llevó al caballo al bosque. De eso nació Sleipnir, el de ocho patas.", en: "Loki became a mare and led the stallion into the woods. From that came Sleipnir, the eight-legged." },
  "ek.cu_4_eromash": { es: "Nunca prometas lo que no querés pagar.", en: "Never promise what you don't want to pay." },
  "ek.cu_5_titulo": { es: "El martillo robado", en: "The stolen hammer" },
  "ek.cu_5_0": { es: "Una mañana Thor se despertó sin su martillo. El gigante Thrym lo había enterrado ocho leguas bajo la tierra.", en: "One morning Thor woke without his hammer. The giant Thrym had buried it eight leagues underground." },
  "ek.cu_5_1": { es: "Thrym lo devolvería solo si le daban a Freyja por esposa. Freyja se enojó tanto que se le rompió el collar.", en: "Thrym would return it only if Freyja was given as his bride. Freyja grew so angry her necklace burst." },
  "ek.cu_5_2": { es: "Entonces vistieron a Thor de novia, con velo, y Loki fue de criada.", en: "So they dressed Thor as the bride, veiled, and Loki went as the maid." },
  "ek.cu_5_3": { es: "En el banquete pusieron el martillo en la falda de la novia para bendecirla. Thor sonrió bajo el velo.", en: "At the feast they laid the hammer in the bride's lap to bless her. Thor smiled beneath the veil." },
  "ek.cu_5_eromash": { es: "Con un velo y paciencia también se gana.", en: "A veil and patience can win too." },
  "ek.cu_6_titulo": { es: "La muerte de Baldr", en: "The death of Baldr" },
  "ek.cu_6_0": { es: "Baldr soñaba con su muerte, y su madre Frigg hizo jurar a todas las cosas que no le harían daño.", en: "Baldr dreamed of his death, and his mother Frigg made every thing swear never to harm him." },
  "ek.cu_6_1": { es: "Se olvidó del muérdago, por chico. Los dioses jugaban a tirarle cosas a Baldr, y nada lo tocaba.", en: "She overlooked the mistletoe, for being small. The gods made a game of throwing things at Baldr, and nothing touched him." },
  "ek.cu_6_2": { es: "Loki le dio una rama de muérdago al ciego Höðr y le guió la mano.", en: "Loki gave a sprig of mistletoe to blind Höðr and guided his hand." },
  "ek.cu_6_3": { es: "Baldr cayó, y todo el mundo lo lloró, menos una giganta en una cueva. Por ella no volvió.", en: "Baldr fell, and the whole world wept for him, all but one giantess in a cave. Because of her, he never returned." },
  "ek.cu_6_eromash": { es: "Lo chico que nadie mira es lo que más pesa.", en: "The small thing no one watches is what weighs the most." },
  "ek.cu_7_titulo": { es: "Skaði elige por los pies", en: "Skaði chooses by the feet" },
  "ek.cu_7_0": { es: "Skaði llegó armada a Asgard a cobrar la muerte de su padre, el gigante Þjazi.", en: "Skaði came armed to Asgard to avenge her father, the giant Þjazi." },
  "ek.cu_7_1": { es: "Los dioses le ofrecieron un esposo, pero tenía que elegirlo mirándoles solo los pies.", en: "The gods offered her a husband, but she had to choose him looking only at their feet." },
  "ek.cu_7_2": { es: "Eligió los más lindos, creyendo que eran de Baldr. Eran de Njörðr, el del mar.", en: "She picked the fairest, thinking they were Baldr's. They were Njörðr's, lord of the sea." },
  "ek.cu_7_3": { es: "Ella no soportaba las gaviotas y él no soportaba los lobos. Se separaron, y cada uno volvió a lo suyo.", en: "She couldn't stand the gulls and he couldn't stand the wolves. They parted, and each went home." },
  "ek.cu_7_eromash": { es: "Montaña y mar. Ninguno de los dos estaba equivocado.", en: "Mountain and sea. Neither of them was wrong." },
  "ek.rn_accion": { es: "Acompañar la ronda", en: "Join the night watch" },
  "ek.rn_pide": { es: "¿Venís con nosotros? Seguinos el paso y abrí bien los ojos.", en: "Coming with us? Keep pace and keep your eyes open." },
  "ek.rn_empieza": { es: "Acompañá la ronda {0} s sin alejarte", en: "Walk with the watch for {0} s without straying" },
  "ek.rn_espera": { es: "La ronda sigue sin vos: volvé con ellos", en: "The watch walks on without you: catch up" },
  "ek.rn_corta": { es: "Te alejaste de la ronda", en: "You strayed from the watch" },
  "ek.rn_gracias": { es: "Noche tranquila. Con alguien como vos al lado, mejor. Tomá, por las piernas.", en: "Quiet night. Better with someone like you along. Here, for your legs." },
  "ek.rn_premio": { es: "La Guardia te paga {0} por la ronda", en: "The Guard pays you {0} for the watch" },
  "ek.rn_dice_0": { es: "La puerta de Sten otra vez sin tranca.", en: "Sten's door unbarred again." },
  "ek.rn_dice_1": { es: "Si el viento cambia, mañana llueve.", en: "If the wind turns, it rains tomorrow." },
  "ek.rn_dice_2": { es: "Ese farol se apagó. Anotalo.", en: "That lamp went out. Note it." },
  "ek.rn_dice_3": { es: "En la curtiembre siempre huele igual, de día o de noche.", en: "The tannery always smells the same, day or night." },
  "ek.rn_dice_4": { es: "Mi abuela decía que los álfar bailan en esta calle.", en: "My grandmother said the álfar dance on this street." },
  "ek.rn_dice_5": { es: "Tres vueltas más y a dormir.", en: "Three more rounds and then bed." },
  "ek.rn_dice_ruido": { es: "¿Oíste eso? … Ah. Un gato. Siempre es un gato.", en: "Did you hear that? … Ah. A cat. It's always a cat." },
  "ek.pt_accion": { es: "Tirar piedras al agua · récord {0}", en: "Skip stones · best {0}" },
  "ek.pt_empieza": { es: "{0} piedras chatas: primero el ángulo, después la fuerza", en: "{0} flat stones: angle first, then strength" },
  "ek.pt_paso_angulo": { es: "Elegí el ángulo: bajo, en la franja verde", en: "Pick the angle: low, in the green band" },
  "ek.pt_paso_fuerza": { es: "Ahora la fuerza", en: "Now the strength" },
  "ek.pt_rebotes": { es: "{0} rebotes", en: "{0} skips" },
  "ek.pt_ayuda": { es: "{0} o E · quedan {1} piedras · {2} rebotes es para presumir", en: "{0} or E · {1} stones left · {2} skips is worth bragging about" },
  "ek.pt_bien": { es: "{0} rebotes. Ni los chicos del muelle llegan a tanto.", en: "{0} skips. Not even the dock kids reach that." },
  "ek.pt_medio": { es: "{0} rebotes. Nada mal para un brazo de hacha.", en: "{0} skips. Not bad for an axe arm." },
  "ek.pt_flojo": { es: "{0}. La piedra quería hundirse.", en: "{0}. The stone wanted to sink." },
  "ek.pt_record": { es: "Nuevo récord en el muelle: {0} rebotes", en: "New best at the dock: {0} skips" },
  "ek.bl_accion": { es: "Sumarse a la ronda del blót", en: "Join the blót dance" },
  "ek.bl_suma": { es: "Te toman de las manos y la ronda sigue girando", en: "They take your hands and the ring keeps turning" },
  "ek.bl_fin": { es: "Hacía mucho que no bailaba. Los pies se acuerdan.", en: "It's been long since I danced. The feet remember." },
  "ek.bl_animo": { es: "Ánimo del blót: +10 de estamina por medio día", en: "Blót cheer: +10 stamina for half a day" },
  "ek.bl_otra": { es: "Otra vuelta de ronda, por el gusto", en: "Another turn of the ring, just for joy" },
  "ek.hoy_blot": { es: "esta noche es el blót: ronda al lado del Roble de 19 a 24", en: "tonight is the blót: dancing beside the Oak from 19 to 24" },
  "ek.hoy_blot_en": { es: "el próximo blót es en {0} días", en: "the next blót is in {0} days" },
  "ek.cg_levantar": { es: "Cargar una caja de pescado ({0} de {1})", en: "Lift a crate of fish ({0} of {1})" },
  "ek.cg_llevala": { es: "Llevala al secadero de la orilla: con peso no se corre", en: "Carry it to the drying rack on the bank: no running with a load" },
  "ek.cg_dejar": { es: "Dejar la caja en el secadero", en: "Set the crate by the drying rack" },
  "ek.cg_una": { es: "Caja en el secadero: {0} de {1}", en: "Crate at the rack: {0} of {1}" },
  "ek.cg_listo": { es: "Tres cajas. Huelo a río hasta la barba.", en: "Three crates. I smell of river down to my beard." },
  "ek.cg_premio": { es: "Los pescadores te dan {0} de plata y un pescado", en: "The fishers give you {0} silver and a fish" },
  "ek.hoy_carga": { es: "a la mañana (6 a 10) los pescadores necesitan manos en el muelle", en: "in the morning (6 to 10) the fishers need hands at the dock" },
  "ek.hu_accion": { es: "Cosechar · cantero de {0}", en: "Harvest · {0} bed" },
  "ek.hu_cosecha": { es: "+{0} {1} de la huerta de Thora", en: "+{0} {1} from Thora's garden" },
  "ek.pd_accion_hablar": { es: "Hablar · Vecina preocupada", en: "Talk · Worried townswoman" },
  "ek.pd_accion_devolver": { es: "Devolver lo que encontraste", en: "Return what you found" },
  "ek.pd_accion_levantar": { es: "Levantar {0}", en: "Pick up {0}" },
  "ek.pd_pide": { es: "¡Ay, forastero! Perdí {0} cerca de {1}. Si lo ves brillar en el piso, traémelo, por favor.", en: "Oh, outsider! I lost {0} near {1}. If you see it glinting on the ground, bring it to me, please." },
  "ek.pd_buscar": { es: "Buscá {0} cerca de {1}: brilla en el piso", en: "Look for {0} near {1}: it glints on the ground" },
  "ek.pd_hallado": { es: "Encontraste {0}: devolvéselo a la vecina del pozo", en: "You found {0}: return it to the woman by the well" },
  "ek.pd_devuelvo": { es: "Creo que esto es tuyo: {0}.", en: "I think this is yours: {0}." },
  "ek.pd_ya": { es: "Gracias otra vez. Mañana seguro pierdo otra cosa, así soy.", en: "Thanks again. Tomorrow I'll surely lose something else, that's how I am." },
  "ek.pd_premio": { es: "Lo devolviste: +{0} de plata", en: "You returned it: +{0} silver" },
  "ek.pd_cosa_0": { es: "el broche de mi abuela", en: "my grandmother's brooch" },
  "ek.pd_cosa_1": { es: "mi anillo de bodas", en: "my wedding ring" },
  "ek.pd_cosa_2": { es: "la llave del arcón", en: "the chest key" },
  "ek.pd_cosa_3": { es: "mi peine de hueso", en: "my bone comb" },
  "ek.pd_cosa_4": { es: "el amuleto de mi hijo", en: "my son's amulet" },
  "ek.pd_cosa_5": { es: "el cuchillo de mi marido", en: "my husband's knife" },
  "ek.pd_gracias_0": { es: "¡El broche! Lo llevaba cuando llegó a Eikholt con nada más que eso. Gracias.", en: "The brooch! She wore it when she came to Eikholt with nothing else. Thank you." },
  "ek.pd_gracias_1": { es: "¡Mi anillo! Si mi marido se enteraba, no me lo perdonaba nunca.", en: "My ring! If my husband had found out, he'd never have forgiven me." },
  "ek.pd_gracias_2": { es: "La llave… sin ella no tenía cómo sacar la ropa de invierno. Gracias.", en: "The key… without it I couldn't get out the winter clothes. Thank you." },
  "ek.pd_gracias_3": { es: "Mi peine. Parece poca cosa, pero lo talló mi padre.", en: "My comb. It seems like little, but my father carved it." },
  "ek.pd_gracias_4": { es: "El amuleto de Tyr de mi hijo. Esta noche duerme tranquilo.", en: "My son's Tyr amulet. Tonight he'll sleep soundly." },
  "ek.pd_gracias_5": { es: "¡El cuchillo! Ya me veía cortando el pan con los dientes.", en: "The knife! I could already see myself cutting bread with my teeth." },
  "ek.hoy_titulo": { es: "Hoy en Eikholt", en: "Today in Eikholt" },
  "ek.hoy_ting": { es: "asamblea en el Ting de 11 a 13", en: "assembly at the Ting from 11 to 13" },
  "ek.hoy_ting_en": { es: "asamblea del Ting en {0} días", en: "Ting assembly in {0} days" },
  "ek.hoy_ladron": { es: "un ratero ronda el mercado de 13 a 15", en: "a thief prowls the market from 13 to 15" },
  "ek.hoy_perdido": { es: "la vecina del pozo perdió algo", en: "the woman by the well lost something" },
  "ek.hoy_perdido_donde": { es: "{0}, cerca de {1}", en: "{0}, near {1}" },
  "ek.hoy_recado": { es: "recado: llevar {0}", en: "errand: deliver {0}" },
  "ek.hoy_promesa": { es: "tu cinta pide {0}", en: "your ribbon asks for {0}" },
  "ek.hoy_tafl": { es: "los viejos juegan al hnefatafl (10 a 18)", en: "the old folks play hnefatafl (10 to 18)" },
  "ek.hoy_huerta": { es: "hay canteros a punto en la huerta de hierbas", en: "herb beds are ready in the healing garden" },
  "ek.pregon_hongos_0": { es: "¡Hongos del bosque, recién juntados!", en: "Forest mushrooms, freshly picked!" },
  "ek.pregon_hongos_1": { es: "¡Musgo de piedra para las heridas!", en: "Stone moss for your wounds!" },
  "ek.pregon_hongos_2": { es: "¡Hongo de luna, el que brilla de noche!", en: "Moon mushroom, the one that glows at night!" },
  "ek.pregon_hongos_3": { es: "¡Para el caldo y para la fiebre, acá!", en: "For the stew and for the fever, right here!" },
  "ek.pregon_pescado_0": { es: "¡Pescado ahumado del río, todavía tibio!", en: "Smoked river fish, still warm!" },
  "ek.pregon_pescado_1": { es: "¡Truchas de esta mañana!", en: "Trout from this very morning!" },
  "ek.pregon_pescado_2": { es: "¡Para la fogata del camino, pescado!", en: "Fish for your campfire on the road!" },
  "ek.pregon_pescado_3": { es: "¡Ahumado con aliso, no hay otro igual!", en: "Smoked over alder, there's none like it!" },
  "ek.pregon_pieles_0": { es: "¡Cuero curtido por Bolli, del bueno!", en: "Leather tanned by Bolli, the good stuff!" },
  "ek.pregon_pieles_1": { es: "¡Pieles para el invierno largo!", en: "Furs for the long winter!" },
  "ek.pregon_pieles_2": { es: "¡Cuero para la forja de Ása!", en: "Leather for Ása's forge!" },
  "ek.pregon_pieles_3": { es: "¡Lobo, zorro y ciervo, elegí!", en: "Wolf, fox and deer, take your pick!" },
  "ek.pregon_hierbas_0": { es: "¡Hierbas de Thora, las que curan!", en: "Thora's herbs, the ones that heal!" },
  "ek.pregon_hierbas_1": { es: "¡Serbal y abedul para el matraz!", en: "Rowan and birch for the flask!" },
  "ek.pregon_hierbas_2": { es: "¡Secadas a la sombra, como debe ser!", en: "Dried in the shade, as it should be!" },
  "ek.pregon_hierbas_3": { es: "¡Para la tos, para el golpe, para el frío!", en: "For the cough, for the bruise, for the cold!" },
  "ek.pregon_ceramica_0": { es: "¡Jarras que no se rajan con el fuego!", en: "Jugs that won't crack in the fire!" },
  "ek.pregon_ceramica_1": { es: "¡Cuencos para el caldo, mirá sin compromiso!", en: "Bowls for your stew, look all you like!" },
  "ek.pregon_ceramica_2": { es: "¡Barro del río, horneado tres días!", en: "River clay, fired for three days!" },
  "ek.pregon_ceramica_3": { es: "¡Una jarra para la hidromiel de Ulf!", en: "A jug for Ulf's mead!" },
  "ek.pregon_sogas_0": { es: "¡Sogas de Folke, aguantan un buey!", en: "Folke's ropes, they'll hold an ox!" },
  "ek.pregon_sogas_1": { es: "¡Cuerda de cáñamo, torcida a mano!", en: "Hemp cord, twisted by hand!" },
  "ek.pregon_sogas_2": { es: "¡Para el barco, para el pozo, para todo!", en: "For the boat, for the well, for everything!" },
  "ek.pregon_sogas_3": { es: "¡Soga alquitranada, no le entra el agua!", en: "Tarred rope, water won't get in!" },
  "ek.pregon_obsidiana_0": { es: "¡Obsidiana de las tierras de ceniza!", en: "Obsidian from the ash lands!" },
  "ek.pregon_obsidiana_1": { es: "¡Brasa que no se apaga, para la forja!", en: "Embers that never die, for the forge!" },
  "ek.pregon_obsidiana_2": { es: "¡Vidrio negro de los volcanes!", en: "Black glass from the volcanoes!" },
  "ek.pregon_obsidiana_3": { es: "¡De muy lejos, y se nota!", en: "From far away, and it shows!" },
  "ek.pregon_lingotes_0": { es: "¡Hierro de montaña, sin escoria!", en: "Mountain iron, no slag!" },
  "ek.pregon_lingotes_1": { es: "¡Lingotes para la herrería!", en: "Ingots for the smithy!" },
  "ek.pregon_lingotes_2": { es: "¡Del otro lado de los picos, hierro bueno!", en: "From beyond the peaks, good iron!" },
  "ek.pregon_lingotes_3": { es: "¡Pesado y parejo, tocalo!", en: "Heavy and even, feel it!" },
  "ek.pregon_hueso_0": { es: "¡Tallas de hueso, cada una distinta!", en: "Bone carvings, each one different!" },
  "ek.pregon_hueso_1": { es: "¡Peines y amuletos de ballena!", en: "Whalebone combs and charms!" },
  "ek.pregon_hueso_2": { es: "¡Una runa tallada para la suerte!", en: "A carved rune for luck!" },
  "ek.pregon_hueso_3": { es: "¡Hechas a cuchillo, en el norte!", en: "Knife-carved, up north!" },
  "ek.pregon_sal_0": { es: "¡Sal de la costa y carne salada!", en: "Coastal salt and salted meat!" },
  "ek.pregon_sal_1": { es: "¡Hierba de escarcha, de las tierras frías!", en: "Frost herb, from the cold lands!" },
  "ek.pregon_sal_2": { es: "¡Jabalí en sal, dura todo el viaje!", en: "Salted boar, lasts the whole journey!" },
  "ek.pregon_sal_3": { es: "¡Sal gruesa, para que nada se eche a perder!", en: "Coarse salt, so nothing spoils!" },
  "ek.ting_accion": { es: "Escuchar al Ting", en: "Listen to the Ting" },
  "ek.ting_titulo": { es: "La asamblea del Ting", en: "The Ting assembly" },
  "ek.ting_abre": { es: "¡Silencio bajo el Roble! El Ting está abierto y cualquiera que tenga voz puede darla.", en: "Silence beneath the Oak! The Ting is open and anyone with a voice may give it." },
  "ek.ting_antes": { es: "Antes de empezar: lo de la última asamblea quedó así: {0}", en: "Before we begin, here is how the last assembly's matter turned out: {0}" },
  "ek.ting_pide": { es: "Forastero, estás en el anillo. ¿De qué lado das tu voz?", en: "Outsider, you stand in the ring. Which side do you give your voice to?" },
  "ek.ting_callar": { es: "Escuchar y no decir nada", en: "Listen and say nothing" },
  "ek.ting_sigue": { es: "La asamblea te escuchó. Se decide así: {0}", en: "The assembly heard you. So it is decided: {0}" },
  "ek.ting_otro": { es: "Te escuchamos, pero la mayoría piensa distinto. Se decide así: {0}", en: "We heard you, but most think otherwise. So it is decided: {0}" },
  "ek.ting_dado": { es: "Diste tu voz en el Ting", en: "You gave your voice at the Ting" },
  "ek.ting_0": { es: "Los leñadores quieren talar el soto del norte para el invierno. Los guardasendas dicen que ahí anidan los cuervos de Odín.", en: "The woodcutters want to fell the northern copse for winter. The pathwardens say Odin's ravens nest there." },
  "ek.ting_0_a": { es: "Que talen: el invierno no espera", en: "Let them cut: winter won't wait" },
  "ek.ting_0_b": { es: "Que dejen el soto en paz", en: "Leave the copse in peace" },
  "ek.ting_0_a_hecho": { es: "se taló el soto y hay leña de sobra, pero los cuervos se mudaron.", en: "the copse was felled and there's firewood to spare, but the ravens moved away." },
  "ek.ting_0_b_hecho": { es: "el soto quedó en pie y los cuervos siguen cantando sobre la muralla.", en: "the copse still stands and the ravens still caw over the wall." },
  "ek.ting_1": { es: "Un mercader de la costa pide quedarse todo el invierno con su puesto en la plaza, sin pagar el lugar.", en: "A coastal merchant asks to keep his stall in the square all winter without paying for the spot." },
  "ek.ting_1_a": { es: "Que se quede: trae sal y noticias", en: "Let him stay: he brings salt and news" },
  "ek.ting_1_b": { es: "Que pague como todos", en: "He pays like everyone else" },
  "ek.ting_1_a_hecho": { es: "el mercader se quedó y ahora hay sal de la costa todo el año.", en: "the merchant stayed and now there's coastal salt all year round." },
  "ek.ting_1_b_hecho": { es: "el mercader pagó refunfuñando, y la caja de la ciudad lo agradece.", en: "the merchant paid grumbling, and the city's chest is grateful." },
  "ek.ting_2": { es: "Dos familias pelean por el agua del pozo de abajo. Una pide turnos; la otra, cavar otro pozo.", en: "Two families quarrel over the lower well. One wants turns; the other wants to dig a new well." },
  "ek.ting_2_a": { es: "Turnos, y que nadie se pase", en: "Turns, and nobody cheats" },
  "ek.ting_2_b": { es: "Cavar otro pozo entre todos", en: "Dig another well together" },
  "ek.ting_2_a_hecho": { es: "hay turnos para el pozo y Gudrun lleva la cuenta con un palo.", en: "there are turns at the well and Gudrun keeps count with a stick." },
  "ek.ting_2_b_hecho": { es: "se cavó otro pozo y las dos familias comparten la soga.", en: "another well was dug and both families share the rope." },
  "ek.ting_3": { es: "La Guardia quiere cerrar la Puerta del Este de noche, por lo que baja del bosque.", en: "The Guard wants to shut the East Gate at night, because of what comes down from the forest." },
  "ek.ting_3_a": { es: "Cerrarla: primero la gente", en: "Shut it: people come first" },
  "ek.ting_3_b": { es: "Dejarla abierta para los que vuelven", en: "Keep it open for those coming home" },
  "ek.ting_3_a_hecho": { es: "la Puerta del Este se cierra al caer el sol y la ronda duerme tranquila.", en: "the East Gate closes at sundown and the watch sleeps easier." },
  "ek.ting_3_b_hecho": { es: "la Puerta del Este sigue abierta y una antorcha espera a los que vuelven tarde.", en: "the East Gate stays open and a torch waits for those who come back late." },
  "ek.ting_4": { es: "El skald Sølve pide que la canción de la primavera hable de los que no volvieron del bosque.", en: "Sølve the skald asks that the spring song tell of those who never came back from the forest." },
  "ek.ting_4_a": { es: "Que los nombre a todos", en: "Let it name them all" },
  "ek.ting_4_b": { es: "Que sea una canción alegre", en: "Let it be a happy song" },
  "ek.ting_4_a_hecho": { es: "la canción nombra a cada uno y en el Hongo nadie habla mientras suena.", en: "the song names every one and nobody speaks in the Mushroom while it plays." },
  "ek.ting_4_b_hecho": { es: "la canción es alegre y hasta Ulf bailó encima de la barra.", en: "the song is cheerful and even Ulf danced on the bar." },
  "ek.ting_5": { es: "Hay que decidir si la hidromiel del invierno largo se abre para la fiesta o se guarda para los malos tiempos.", en: "We must decide whether the long-winter mead is opened for the feast or kept for hard times." },
  "ek.ting_5_a": { es: "Abrirla: la fiesta también cura", en: "Open it: a feast heals too" },
  "ek.ting_5_b": { es: "Guardarla para cuando haga falta", en: "Keep it for when it's needed" },
  "ek.ting_5_a_hecho": { es: "se abrió la cuba vieja y la fiesta duró hasta el alba.", en: "the old vat was opened and the feast lasted until dawn." },
  "ek.ting_5_b_hecho": { es: "la cuba sigue sellada en la bodega de Ulf, esperando.", en: "the vat is still sealed in Ulf's cellar, waiting." },
  "av.nombre_ek_farolero": { es: "Farolero", en: "Lamplighter" },
  "av.nombre_ek_borracho": { es: "Parroquiano del Hongo", en: "Mushroom regular" },
  "av.nombre_ek_ladron": { es: "Ratero", en: "Pickpocket" },
  "ek.esc_accion": { es: "Jugar a las escondidas con los chicos", en: "Play hide-and-seek with the kids" },
  "ek.esc_accion_hallar": { es: "¡Te encontré, {0}!", en: "Found you, {0}!" },
  "ek.esc_pide": { es: "¿Jugás? ¡Vos contás! Tapate los ojos hasta cien y no espíes.", en: "Want to play? You're it! Cover your eyes and count to a hundred, no peeking." },
  "ek.esc_cuento": { es: "Uno… dos… tres… noventa y nueve… ¡cien! ¡Allá voy!", en: "One… two… three… ninety-nine… a hundred! Ready or not!" },
  "ek.esc_no": { es: "Ahora no, que no estamos todos. Volvé más tarde.", en: "Not now, we're not all here. Come back later." },
  "ek.esc_empieza": { es: "Escondidas: encontrá a los chicos ({0} s)", en: "Hide-and-seek: find the kids ({0} s)" },
  "ek.esc_hallado": { es: "Encontraste a {0} ({1}/{2})", en: "You found {0} ({1}/{2})" },
  "ek.esc_quedan": { es: "Quedan {0} s", en: "{0} s left" },
  "ek.esc_risa_norte": { es: "Se oye una risita hacia el norte", en: "A giggle comes from the north" },
  "ek.esc_risa_sur": { es: "Se oye una risita hacia el sur", en: "A giggle comes from the south" },
  "ek.esc_risa_este": { es: "Se oye una risita hacia el este", en: "A giggle comes from the east" },
  "ek.esc_risa_oeste": { es: "Se oye una risita hacia el oeste", en: "A giggle comes from the west" },
  "ek.esc_ganaste": { es: "¡Nos encontraste a todos! Tomá, es lo que juntamos vendiendo bellotas.", en: "You found all of us! Here, it's what we got selling acorns." },
  "ek.esc_otra": { es: "¡Otra vez nos encontraste! Mañana nos escondemos mejor.", en: "You found us again! Tomorrow we'll hide better." },
  "ek.esc_premio": { es: "Las escondidas: +5 de plata", en: "Hide-and-seek: +5 silver" },
  "ek.esc_perdiste": { es: "¡Se acabó el tiempo! Estaba acá nomás y pasaste dos veces al lado.", en: "Time's up! I was right here and you walked past me twice." },
  "ek.pr_accion": { es: "Atar una cinta de promesa", en: "Tie a promise ribbon" },
  "ek.pr_accion_mirar": { es: "Mirar tu cinta de promesa", en: "Look at your promise ribbon" },
  "ek.pr_titulo": { es: "Las cintas de promesa", en: "The promise ribbons" },
  "ek.pr_sub": { es: "Una cinta cuesta {0} de plata · tenés {1}", en: "A ribbon costs {0} silver · you have {1}" },
  "ek.pr_texto": { es: "Cada cinta es un pedido al Roble. La gente de Eikholt dice que escucha hasta que sale el sol del día siguiente.", en: "Every ribbon is a request to the Oak. The people of Eikholt say it listens until the next day's sunrise." },
  "ek.pr_salud": { es: "Salud", en: "Health" },
  "ek.pr_salud_d": { es: "más vida y se cura más rápido", en: "more health and faster healing" },
  "ek.pr_suerte": { es: "Suerte", en: "Luck" },
  "ek.pr_suerte_d": { es: "más golpes críticos y más plata", en: "more critical hits and more silver" },
  "ek.pr_camino": { es: "Camino", en: "The road" },
  "ek.pr_camino_d": { es: "más rápido y más estamina", en: "faster and more stamina" },
  "ek.pr_ato_salud": { es: "Ato una cinta roja y pido volver entero de cada camino.", en: "I tie a red ribbon and ask to come back whole from every road." },
  "ek.pr_ato_suerte": { es: "Ato una cinta dorada y pido que la suerte me mire de frente.", en: "I tie a golden ribbon and ask luck to look me in the eye." },
  "ek.pr_ato_camino": { es: "Ato una cinta verde y pido piernas que no se cansen.", en: "I tie a green ribbon and ask for legs that never tire." },
  "ek.pr_ya": { es: "Mi cinta ya está atada entre las otras. Pedí {0}; el Roble escucha hasta la mañana.", en: "My ribbon is already tied among the others. I asked for {0}; the Oak listens until morning." },
  "ek.pr_aviso": { es: "Promesa del Roble: {0} hasta la mañana", en: "Oak promise: {0} until morning" },
  "ek.pr_sin_plata": { es: "No te alcanza la plata para una cinta", en: "You don't have enough silver for a ribbon" },
  "ek.pr_se_fue": { es: "Amaneció: tu cinta de promesa se desató", en: "Dawn broke: your promise ribbon came undone" },
  "ek.esp_accion": { es: "Sentarse a esperar", en: "Sit and wait" },
  "ek.esp_titulo": { es: "Sentarse en el Ting", en: "Sit at the Ting" },
  "ek.esp_texto": { es: "La piedra está tibia de sol. Desde acá se ve pasar a toda la ciudad. ¿Hasta cuándo te quedás?", en: "The stone is warm from the sun. From here you can watch the whole city go by. How long will you stay?" },
  "ek.esp_manana": { es: "Hasta la mañana (7)", en: "Until morning (7:00)" },
  "ek.esp_mediodia": { es: "Hasta el mediodía (12)", en: "Until noon (12:00)" },
  "ek.esp_tarde": { es: "Hasta la tarde (17)", en: "Until evening (17:00)" },
  "ek.esp_noche": { es: "Hasta la noche (21)", en: "Until night (21:00)" },
  "ek.esp_paso_manana": { es: "Amanece sobre Eikholt", en: "Dawn breaks over Eikholt" },
  "ek.esp_paso_mediodia": { es: "Es mediodía en Eikholt", en: "It's noon in Eikholt" },
  "ek.esp_paso_tarde": { es: "Cae la tarde sobre Eikholt", en: "Evening falls over Eikholt" },
  "ek.esp_paso_noche": { es: "Es de noche en Eikholt", en: "Night has fallen in Eikholt" },
  "ek.tafl_accion": { es: "Apostar en la partida de hnefatafl", en: "Bet on the hnefatafl game" },
  "ek.tafl_accion_mirar": { es: "Mirar la partida de hnefatafl", en: "Watch the hnefatafl game" },
  "ek.tafl_titulo": { es: "La partida de hnefatafl", en: "The hnefatafl game" },
  "ek.tafl_sub": { es: "La apuesta es de {0} de plata · tenés {1}", en: "The bet is {0} silver · you have {1}" },
  "ek.tafl_texto": { es: "El rey tiene que llegar a una esquina con sus defensores; los atacantes, rodearlo por los cuatro lados. Casi siempre ganan los atacantes.", en: "The king must reach a corner with his defenders; the attackers must surround him on all four sides. The attackers almost always win." },
  "ek.tafl_rey": { es: "Al rey (paga {0})", en: "On the king (pays {0})" },
  "ek.tafl_atac": { es: "A los atacantes (paga {0})", en: "On the attackers (pays {0})" },
  "ek.tafl_mirar": { es: "Solo mirar", en: "Just watch" },
  "ek.tafl_invita": { es: "¿Te sentás a mirar, forastero? Si querés, apostá. Mi mujer juega con el rey y no lo suelta nunca.", en: "Sitting down to watch, outsider? Place a bet if you like. My wife plays the king and never gives him up." },
  "ek.tafl_juega_0": { es: "Te cierro por el norte. Mirá cómo se queda sin aire tu reycito.", en: "I close you off from the north. Watch your little king run out of air." },
  "ek.tafl_juega_1": { es: "Hablás mucho para tener dos piezas colgando. A ver esta…", en: "You talk a lot for someone with two pieces hanging. Let's see this one…" },
  "ek.tafl_fin_rey": { es: "¡Esquina! El rey se escapa. Cuarenta inviernos y todavía no aprendés a cerrar el paso.", en: "Corner! The king escapes. Forty winters and you still haven't learned to block the way." },
  "ek.tafl_fin_atac": { es: "Cuatro lados. El rey cayó. Mañana empezamos otra, y otra vez te gano.", en: "Four sides. The king has fallen. Tomorrow we start another, and I'll beat you again." },
  "ek.tafl_ganaste": { es: "Ganaste la apuesta: +{0} de plata", en: "You won the bet: +{0} silver" },
  "ek.tafl_perdiste": { es: "Perdiste la apuesta", en: "You lost the bet" },
  "ek.tafl_sin_plata": { es: "No te alcanza la plata para apostar", en: "You don't have enough silver to bet" },
  "ek.tafl_dice_0": { es: "Esa pieza no se mueve así, ya te lo dije en la cosecha pasada.", en: "That piece doesn't move like that, I told you last harvest." },
  "ek.tafl_dice_1": { es: "Shh… estoy pensando.", en: "Shh… I'm thinking." },
  "ek.tafl_dice_2": { es: "Si tocás el rey con el codo otra vez, cuenta como captura.", en: "If you bump the king with your elbow again, it counts as a capture." },
  "ek.tafl_dice_3": { es: "El rey solo necesita una esquina. Una.", en: "The king only needs one corner. Just one." },
  "ek.tafl_dice_4": { es: "Veinte años mirándote jugar y seguís abriendo por el mismo lado.", en: "Twenty years watching you play and you still open on the same side." },
  "ek.tafl_dice_5": { es: "¿Quién movió esta? ¿Fuiste vos o fue el viento?", en: "Who moved this one? Was it you or the wind?" },
  "ek.acariciar_perro": { es: "Acariciar al perro", en: "Pet the dog" },
  "ek.acariciar_gato": { es: "Acariciar al gato", en: "Pet the cat" },
  "ek.saludo_dia_0": { es: "¡Salud, forastero! Que el Roble te dé sombra.", en: "Hail, outsider! May the Oak give you shade." },
  "ek.saludo_dia_1": { es: "Pasá, pasá. Con las armas guardadas adentro de la empalizada.", en: "Come in, come in. Keep your weapons sheathed inside the palisade." },
  "ek.saludo_dia_2": { es: "¿Volvés del bosque? Se te ve en las botas.", en: "Back from the forest? It shows on your boots." },
  "ek.saludo_dia_3": { es: "Buen camino. Y si ves lobos cerca del camino, avisá en el cuartel.", en: "Safe travels. And if you see wolves near the road, tell the barracks." },
  "ek.saludo_noche_0": { es: "¿Quién va? Ah, sos vos. Pasá.", en: "Who goes there? Ah, it's you. Go on." },
  "ek.saludo_noche_1": { es: "De noche la puerta se cuida el doble. Que descanses.", en: "At night the gate is watched twice as hard. Rest well." },
  "ek.saludo_noche_2": { es: "No te alejes de los faroles, forastero.", en: "Don't stray from the lamps, outsider." },
  "ek.saludo_noche_3": { es: "Si salís ahora, que sea con buena luz y buena hoja.", en: "If you go out now, go with a good light and a good blade." },
  "ek.cv_accion": { es: "Dejar carne a los cuervos de Odín", en: "Leave meat for Odin's ravens" },
  "ek.cv_deja": { es: "Dejo {0} en la losa. Huginn, Muninn… si me ven, díganme qué se me escapa.", en: "I leave {0} on the slab. Huginn, Muninn… if you see me, tell me what I'm missing." },
  "ek.cv_vuela": { es: "Los cuervos vuelan hacia el {0}: algo espera a {1} m (marcado en el mapa)", en: "The ravens fly {0}: something waits {1} m away (marked on the map)" },
  "ek.cv_nada": { es: "Los cuervos comen y se quedan: ya no queda nada que mostrarte", en: "The ravens eat and stay: there's nothing left to show you" },
  "ek.cv_norte": { es: "norte", en: "north" },
  "ek.cv_noreste": { es: "noreste", en: "northeast" },
  "ek.cv_este": { es: "este", en: "east" },
  "ek.cv_sureste": { es: "sureste", en: "southeast" },
  "ek.cv_sur": { es: "sur", en: "south" },
  "ek.cv_suroeste": { es: "suroeste", en: "southwest" },
  "ek.cv_oeste": { es: "oeste", en: "west" },
  "ek.cv_noroeste": { es: "noroeste", en: "northwest" },
  "ek.dice_recluta_0": { es: "Håkon dice que el muñeco de paja pega más fuerte que yo.", en: "Håkon says the straw dummy hits harder than I do." },
  "ek.dice_recluta_1": { es: "Primero la guardia, después el escudo, después la lanza. Así me lo hacen repetir.", en: "Guard first, then shield, then spear. That's what they make me repeat." },
  "ek.dice_recluta_2": { es: "Mañana me toca la ronda del adarve. Desde arriba se ve hasta el río.", en: "Tomorrow I'm on walkway watch. From up there you can see all the way to the river." },
  "ek.dice_recluta_3": { es: "Dicen que vos peleaste contra el ciervo de las ataduras. ¿Es cierto?", en: "They say you fought the bound stag. Is it true?" },
  "ek.dice_viajero_0": { es: "Tres semanas de camino y la carreta varada en el barro. Bienvenido a Eldervald.", en: "Three weeks on the road and the cart stuck in mud. Welcome to Eldervald." },
  "ek.dice_viajero_1": { es: "Mientras el Paso siga cerrado, los cajones esperan acá. Y nosotros con ellos.", en: "While the Pass stays closed, the crates wait here. And so do we." },
  "ek.dice_viajero_2": { es: "En Jarnskald hay hierro de sobra y nadie que lo compre. Acá es al revés.", en: "In Jarnskald there's iron to spare and nobody to buy it. Here it's the other way round." },
  "ek.dice_viajero_3": { es: "El fuego del corral no se apaga nunca. Siempre hay alguien esperando algo.", en: "The pen fire never goes out. Someone's always waiting for something." },
  "ek.dice_viajero_4": { es: "Pasé por el Puesto de Eydis. Halvard me dio sopa y un consejo que no pedí.", en: "I passed Eydis's Post. Halvard gave me soup and advice I didn't ask for." },
  "ek.dice_viajero_5": { es: "Los bueyes saben el camino mejor que yo. Yo solo grito.", en: "The oxen know the road better than I do. I just shout." },
  "ek.dice_pescador_0": { es: "Una balsa se trabó en los troncos de la curva. Hace dos días que nadie la saca.", en: "A raft got caught on the logs at the bend. Nobody's freed it for two days." },
  "ek.dice_pescador_1": { es: "El río viene del norte, del Paso. Cuando trae hielo, algo anda mal allá arriba.", en: "The river comes from the north, from the Pass. When it carries ice, something's wrong up there." },
  "ek.dice_pescador_2": { es: "Si te caés al agua, no te asustes: lo hondo está más adelante.", en: "If you fall in, don't panic: the deep part is further on." },
  "ek.dice_pescador_3": { es: "El pescado colgado se seca en tres días. El de la noche, en cuatro.", en: "Hung fish dries in three days. The night catch, in four." },
  "ek.dice_guardia_0": { es: "Desde el adarve se ven las doce piedras. Contalas: si una se apaga, avisá.", en: "From the walkway you can see all twelve stones. Count them: if one goes dark, tell us." },
  "ek.dice_guardia_1": { es: "No te apoyes en la baranda. La arreglamos el otoño pasado, pero no confío.", en: "Don't lean on the railing. We fixed it last autumn, but I don't trust it." },
  "ek.dice_guardia_2": { es: "Cada atalaya tiene su farol. Si uno se apaga de noche, alguien no está haciendo su ronda.", en: "Every watchtower has its lantern. If one goes out at night, someone's skipping their round." },
  "ek.dice_guardia_3": { es: "Las caravanas entran por el norte, el rey por el sur. Así fue siempre.", en: "Caravans come in through the north, the king through the south. It's always been that way." },
  "ek.dice_guardia_4": { es: "Lo azul de las raíces no lo ve cualquiera. Si lo ves, no se lo digas a todo el mundo.", en: "Not everyone can see the blue in the roots. If you do, don't tell everybody." },
  "ek.golpear": { es: "Golpear la puerta", en: "Knock on the door" },
  "ek.puerta_0": { es: "«¡Ya va, ya va!»… Pasos, una tranca que se corre a medias y un ojo que mira por la rendija. «No compramos nada.»", en: "“Coming, coming!”… Footsteps, a bar slid halfway and an eye at the crack. “We're not buying anything.”" },
  "ek.puerta_1": { es: "Adentro un perro ladra como si lo fueran a comer. Nadie viene a abrir.", en: "Inside a dog barks as if it were about to be eaten. Nobody comes to the door." },
  "ek.puerta_2": { es: "«¿Sos el de la cuadrilla? Decile a Orm que la paga vino corta.»", en: "“Are you from the crew? Tell Orm the pay came up short.”" },
  "ek.puerta_3": { es: "Silencio. Después, una risa de chicos y alguien que los manda callar.", en: "Silence. Then children laughing and someone hushing them." },
  "ek.puerta_4": { es: "«¡Está abierto!»… No, no está abierto. «¡Empujá más fuerte!»… Sigue sin abrir.", en: "“It's open!”… No, it isn't. “Push harder!”… Still shut." },
  "ek.puerta_5": { es: "Una vieja contesta sin abrir: «Si es por la leña, dejala junto a la pared. Si es por otra cosa, volvé mañana.»", en: "An old woman answers without opening: “If it's the firewood, leave it by the wall. If it's anything else, come back tomorrow.”" },
  "ek.puerta_6": { es: "Huele a pan recién hecho. Una voz grita «¡Ocupada!» y algo se cae al piso.", en: "It smells of fresh bread. A voice shouts “Busy!” and something hits the floor." },
  "ek.puerta_7": { es: "Nadie contesta. En la puerta hay una Othala tallada y una ramita de enebro seca.", en: "No answer. On the door there's a carved Othala and a dry sprig of juniper." },
  "ek.puerta_8": { es: "«¡Gracias por lo de los lobos!», dice alguien detrás de la puerta. «Mi hermano te vio en el camino.»", en: "“Thanks for the wolves!” someone says behind the door. “My brother saw you on the road.”" },
  "ek.puerta_9": { es: "Un gato maúlla del otro lado, como si fuera el dueño de casa. Nadie más contesta.", en: "A cat meows from the other side, as if it owned the place. Nobody else answers." },
  "ek.puerta_noche_0": { es: "Una voz dormida: «¿Quién golpea a esta hora? ¡Andá a dormir!»", en: "A sleepy voice: “Who's knocking at this hour? Go to bed!”" },
  "ek.puerta_noche_1": { es: "Se apaga la vela que se veía por la rendija. Nadie va a abrir de noche.", en: "The candle glimmering through the crack goes out. Nobody opens up at night." },
  "ek.puerta_noche_2": { es: "«Si sos la Cacería, acá no hay nadie.» Después, un susurro: «Seguí de largo.»", en: "“If you're the Hunt, there's nobody here.” Then a whisper: “Keep walking.”" },
  "ek.puerta_noche_3": { es: "Un ronquido largo, como un fuelle. Mejor dejarlos dormir.", en: "A long snore, like a bellows. Better let them sleep." },
  // el Mercado de los Toldos (ciudad/mercado.js)
  "ek.mc_accion_comprar": { es: "Comprar · {0}", en: "Buy · {0}" },
  "ek.mc_accion_mirar": { es: "Mirar · {0}", en: "Look · {0}" },
  "ek.mc_sub": { es: "Tenés {0} de plata. Cada cosa vuelve a las 6 de la mañana.", en: "You have {0} silver. Stock comes back at 6 in the morning." },
  "ek.mc_comprar": { es: "{0} · {1} de plata (quedan {2})", en: "{0} · {1} silver ({2} left)" },
  "ek.mc_agotado": { es: "{0} · agotado hasta mañana", en: "{0} · sold out until tomorrow" },
  "ek.mc_sin_plata": { es: "No te alcanza la plata.", en: "You don't have enough silver." },
  "ek.mc_compraste": { es: "Compraste {0}", en: "You bought {0}" },
  "ek.mc_puesto_hongos": { es: "El puesto de los hongos", en: "The mushroom stall" },
  "ek.mc_puesto_pescado": { es: "El puesto del pescado ahumado", en: "The smoked fish stall" },
  "ek.mc_puesto_pieles": { es: "El puesto de las pieles", en: "The hide stall" },
  "ek.mc_puesto_hierbas": { es: "El puesto de las hierbas", en: "The herb stall" },
  "ek.mc_puesto_ceramica": { es: "El puesto de la cerámica", en: "The pottery stall" },
  "ek.mc_puesto_sogas": { es: "El puesto de las sogas", en: "The rope stall" },
  "ek.mc_puesto_obsidiana": { es: "El puesto de la obsidiana", en: "The obsidian stall" },
  "ek.mc_puesto_lingotes": { es: "El puesto de los lingotes", en: "The ingot stall" },
  "ek.mc_puesto_hueso": { es: "El puesto de las tallas de hueso", en: "The bone carving stall" },
  "ek.mc_puesto_sal": { es: "El puesto de la sal de la costa", en: "The coastal salt stall" },
  "ek.mc_mira_hongos": { es: "Hongos de las camas de Ragna y musgo de las piedras. La puestera jura que el azul brilla de noche.", en: "Mushrooms from Ragna's beds and moss from the stones. The stallholder swears the blue one glows at night." },
  "ek.mc_mira_pescado": { es: "Pescado del río colgado en el humo de enebro. Fresco de la mañana, para la fogata.", en: "River fish hung in juniper smoke. Fresh this morning, for the campfire." },
  "ek.mc_mira_pieles": { es: "Cueros curados de la curtiembre de Bolli, doblados por tamaño. Huelen menos que la curtiembre.", en: "Cured hides from Bolli's tannery, folded by size. They smell less than the tannery." },
  "ek.mc_mira_hierbas": { es: "Manojos atados con hilo rojo: las de Thora para las heridas y otras para el matraz.", en: "Bundles tied with red thread: Thora's for wounds and others for the flask." },
  "ek.mc_mira_ceramica": { es: "Jarras, cuencos y una vasija con la cornamenta pintada. Lindas, pero no se llevan en la mochila.", en: "Jugs, bowls and a pot painted with the antler. Lovely, but they don't fit in a backpack." },
  "ek.mc_mira_sogas": { es: "Rollos de soga de la cordelería de Folke. El nudo de muestra no lo deshace nadie.", en: "Rope coils from Folke's ropewalk. Nobody can undo the sample knot." },
  "ek.mc_mira_obsidiana": { es: "Obsidiana y sales de ceniza de Eldrakar. Una brasa guardada en piedra, para la forja de Ása.", en: "Obsidian and ash salts from Eldrakar. An ember kept in stone, for Ása's forge." },
  "ek.mc_mira_lingotes": { es: "Lingotes de las minas de Jarnskald, con la marca del herrero que los fundió.", en: "Ingots from the Jarnskald mines, stamped by the smith who cast them." },
  "ek.mc_mira_hueso": { es: "Tallas de hueso: un cuervo, un barco, una runa de Othala. El tallador no levanta la vista.", en: "Bone carvings: a raven, a ship, an Othala rune. The carver never looks up." },
  "ek.mc_mira_sal": { es: "Sal de la costa en sacos y panceta salada que aguanta el viaje. Del fondo asoma flor de escarcha de los acantilados.", en: "Coastal salt in sacks and salted bacon that survives the journey. Frostflower from the cliffs peeks from the back." },
  "ek.mc_p_hierbas": { es: "hierbas de Thora", en: "Thora's herbs" },
  // los recados del tablón de la plaza (ciudad/recados.js)
  "ek.rc_accion_tablon": { es: "Leer el tablón", en: "Read the board" },
  "ek.rc_accion_entregar": { es: "Entregar · {0}", en: "Deliver · {0}" },
  "ek.rc_tomado": { es: "Lo despego del tablón y me lo llevo. Paga {0} de plata: la marca del mapa dice adónde.", en: "I take it off the board. It pays {0} silver: the map mark shows where." },
  "ek.rc_falta": { es: "Ya tengo este recado. Primero lo entrego, después miro el tablón.", en: "I already have this errand. Deliver first, then check the board again." },
  "ek.rc_hecho": { es: "Recado entregado · +{0} de plata", en: "Errand delivered · +{0} silver" },
  "ek.rc_0": { es: "«Se busca quien lleve un rollo de cuero a la carpintería de Sten. Es para las bisagras de la balsa.»", en: "“Wanted: someone to carry a roll of leather to Sten's carpentry. It's for the raft's hinges.”" },
  "ek.rc_1": { es: "«Dos bolsas de corteza de roble para la curtiembre. Bolli paga, pero hay que aguantar el olor.»", en: "“Two bags of oak bark for the tannery. Bolli pays, but you have to stand the smell.”" },
  "ek.rc_2": { es: "«Un manojo de milenrama para la Casa de Sanación, antes de que se marchite.»", en: "“A bundle of yarrow for the House of Healing, before it wilts.”" },
  "ek.rc_3": { es: "«Un barrilito de brea para la cordelería de Folke. Cuidado, que mancha.»", en: "“A small keg of pitch for Folke's ropewalk. Careful, it stains.”" },
  "ek.rc_4": { es: "«Una carta sellada para el sargento de la Guardia. No abrir.» Alguien la abrió y la volvió a cerrar.", en: "“A sealed letter for the Guard sergeant. Do not open.” Someone opened it and sealed it again." },
  "ek.rc_5": { es: "«Clavos torcidos para la herrería de Ása, que los endereza por poco.»", en: "“Bent nails for Ása's smithy; she straightens them for cheap.”" },
  "ek.rc_6": { es: "«Una canasta de pan de la mañana para la hospedería de Ragnfrid.»", en: "“A basket of morning bread for Ragnfrid's inn.”" },
  "ek.rc_7": { es: "«Jarras vacías para el Hongo Dorado. Ulf cuenta cada una.»", en: "“Empty jugs for the Golden Mushroom. Ulf counts every one.”" },
  "ek.rc_8": { es: "«Un mapa del vado viejo para la Casa de las Lindes. Ketill lo copia.»", en: "“A map of the old ford for the House of Boundaries. Ketill copies it.”" },
  "ek.rc_cosa_0": { es: "el rollo de cuero", en: "the roll of leather" },
  "ek.rc_cosa_1": { es: "la corteza de roble", en: "the oak bark" },
  "ek.rc_cosa_2": { es: "la milenrama", en: "the yarrow" },
  "ek.rc_cosa_3": { es: "el barrilito de brea", en: "the keg of pitch" },
  "ek.rc_cosa_4": { es: "la carta sellada", en: "the sealed letter" },
  "ek.rc_cosa_5": { es: "los clavos torcidos", en: "the bent nails" },
  "ek.rc_cosa_6": { es: "la canasta de pan", en: "the bread basket" },
  "ek.rc_cosa_7": { es: "las jarras vacías", en: "the empty jugs" },
  "ek.rc_cosa_8": { es: "el mapa del vado", en: "the ford map" },
  "ek.rc_0_gracias": { es: "Justo lo que faltaba. Sin bisagras, la balsa se abre como una boca. Tomá.", en: "Just what was missing. Without hinges, the raft opens like a mouth. Here." },
  "ek.rc_1_gracias": { es: "¿No te mareaste en el camino? Bien. Acá está lo tuyo.", en: "Didn't get dizzy on the way? Good. Here's yours." },
  "ek.rc_2_gracias": { es: "Todavía huele a campo. Con esto aguanta la herida de Bjarki una semana más.", en: "Still smells of the field. With this Bjarki's wound will hold another week." },
  "ek.rc_3_gracias": { es: "Ni una gota en el piso. Vos sabés llevar cosas.", en: "Not a drop on the floor. You know how to carry things." },
  "ek.rc_4_gracias": { es: "El sello está roto y pegado con cera de vela. Ya sé quién fue. Gracias igual.", en: "The seal is broken and stuck with candle wax. I know who did it. Thanks anyway." },
  "ek.rc_5_gracias": { es: "Clavos torcidos, hierro bueno. Los dejo derechos antes de la cena.", en: "Bent nails, good iron. I'll have them straight before supper." },
  "ek.rc_6_gracias": { es: "¡Todavía tibio! Los caminantes te lo van a agradecer sin saberlo.", en: "Still warm! The travelers will thank you without knowing it." },
  "ek.rc_7_gracias": { es: "Una, dos… doce. Están todas. Raro. Tomá.", en: "One, two… twelve. All here. Strange. Here." },
  "ek.rc_8_gracias": { es: "El vado viejo… Svanhild lo buscaba. Lo copio esta noche.", en: "The old ford… Svanhild was looking for it. I'll copy it tonight." },
});
